{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Grazoprevir, the closest analogue (Morgan 0.4328), has an absolute oral bioavailability of 27% in humans, directly supporting F ≥20% for this closely related macrocyclic HCV protease inhibitor scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Grazoprevir bioavailability was 24–40% after multiple 200 mg daily doses in healthy subjects, corroborating that this scaffold can achieve F ≥20% at therapeutic doses.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "A single 25 mg grazoprevir dose gave 10–17% bioavailability, showing dose-dependent first-pass effects; this is contradictory evidence but at a lower dose and less representative of therapeutic exposure.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Danoprevir, a less similar macrocyclic HCV protease inhibitor (Morgan 0.2778), has absolute oral bioavailability of only 1.15% due to extensive first-pass metabolism/efflux, supporting low; however its lower transferability limits weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most transferable experimental evidence (grazoprevir, Morgan 0.4328) shows absolute oral bioavailability of 27% and 24–40%, exceeding the 20% threshold. Although the physicochemical prior is low and a less similar analogue (danoprevir) has very low F, the structural similarity to grazoprevir and direct human absolute bioavailability data outweigh these concerns. Prediction: high.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "Closest analogue grazoprevir differs in the macrocyclic P2 aromatic/linker region.",
    "Grazoprevir bioavailability is dose-dependent (10–17% at 25 mg vs 27% at therapeutic doses), so exact exposure for the query is uncertain.",
    "No data on formulation, food effects, or transporter involvement for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

